"""
    Get ".ext" (extension) of string "_str".

    Args:
        _str (str)

    Returns:
        ext (str)
            extension of _str

    Example:
        | >> get_extension("random_plot.png")
        | ".png"
    """
def get_extension(_str: Any) -> object {
    _str = str(_str).rsplit("/", 1)[-1];
    ext = "." + _str.rsplit(".", 1)[-1];
    return ext;
}

